JOIN dbo.users cu ON cu.username = v.convusername
JOIN dbo.students cst ON cst.user_id = cu.user_id
JOIN dbo.chat_conversations conv ON conv.student_id = cst.student_id AND conv.created_at = v.convcreated
JOIN dbo.users su ON su.username = v.senderusername;

